package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.math.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class PerfSummaryProvider extends AbstractLabDataSourceProvider { private static final String PERMISSION="lab:report:sensitive"; public PerfSummaryProvider(){super(ReportConfigCatalog.PERF_SUMMARY,new LinkedHashSet<String>(Arrays.asList("period","memberId","resultStatus","score","revisionNo","redLineFlag","confirmationStatus")));} @Override protected boolean supports(ReportPeriod.Kind kind){return kind==ReportPeriod.Kind.MONTH||kind==ReportPeriod.Kind.QUARTER;} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){if(!c.getScope().hasPermission(PERMISSION))throw new SecurityException("Missing report sensitive permission");List<Map<String,Object>>r=copyRows(mapper().selectCurrentPerfScores(c));BigDecimal total=BigDecimal.ZERO;for(Map<String,Object>x:r)total=total.add(number(x.get("score")));Map<String,Object>z=summaryCount(r);z.put("averageScore",r.isEmpty()?BigDecimal.ZERO:total.divide(BigDecimal.valueOf(r.size()),2,RoundingMode.HALF_UP));return section(c,s,r,z);}}
